INSERT INTO it_glossary (term_ja, reading, term_ko, term_en, category, description, example_sentence) VALUES
INSERT INTO it_glossary (term_ja, reading, term_ko, term_en, category, description, example_sentence) VALUES
  ('SQL', 'エスキューエル', 'SQL', 'Structured Query Language', 'it', '데이터베이스를 조작하고 관리하기 위한 표준 프로그래밍 언어입니다.', 'SQLを使ってデータベースからデータを取得してください。'),
  ('データベース', 'データベース', '데이터베이스', 'Database', 'it', '대량의 데이터를 체계적으로 정리하여 저장하고 검색할 수 있도록 한 시스템입니다.', 'データベースの構造を設計してからテーブルを作成します。'),
  ('正規化', 'せいきか', '정규화', 'Normalization', 'it', '데이터의 중복을 없애고 일관성을 유지하기 위해 테이블 구조를 최적화하는 과정입니다.', '正規化を行ってデータの重複を排除しましょう。'),
  ('主キー', 'しゅきー', '기본키', 'Primary Key', 'it', '테이블에서 각 행(레코드)을 고유하게 식별하기 위한 열(컬럼)입니다. 중복값을 가질 수 없습니다.', 'テーブルに主キーを設定してレコードを一意に識別できるようにします。'),
  ('外部キー', 'がいぶきー', '외래키', 'Foreign Key', 'it', '다른 테이블의 기본키를 참조하여 테이블 간의 관계를 정의하는 열입니다.', '外部キーを設定してテーブル間の参照整合性を保ちます。'),
  ('トランザクション', 'トランザクション', '트랜잭션', 'Transaction', 'it', '데이터베이스에 대한 일련의 처리를 하나의 단위로 묶은 것입니다. 전부 성공하거나 전부 취소됩니다.', 'トランザクションを使って複数の更新処理をまとめて実行します。'),
  ('ACID特性', 'アシッドとくせい', 'ACID 특성', 'ACID Properties', 'it', '트랜잭션이 안전하게 처리되기 위한 4가지 조건(원자성, 일관성, 독립성, 영속성)입니다.', 'ACID特性を満たすことでデータの整合性が保証されます。'),
  ('インデックス', 'インデックス', '인덱스', 'Index', 'it', '데이터베이스에서 검색 속도를 높이기 위해 만드는 색인입니다. 책의 목차와 비슷한 역할을 합니다.', 'よく検索されるカラムにインデックスを作成してパフォーマンスを改善します。'),
  ('ビュー', 'ビュー', '뷰', 'View', 'it', '하나 이상의 테이블에서 필요한 데이터만 골라 만든 가상 테이블입니다.', 'ビューを作成して必要なカラムだけを表示するようにしました。'),
  ('ストアドプロシージャ', 'ストアドプロシージャ', '저장 프로시저', 'Stored Procedure', 'it', '자주 사용하는 SQL 처리를 미리 데이터베이스에 저장해두고 호출하여 사용하는 프로그램입니다.', 'ストアドプロシージャを使って複雑な処理をサーバー側で実行します。'),
  ('トリガー', 'トリガー', '트리거', 'Trigger', 'it', '데이터베이스에서 특정 이벤트(삽입, 수정, 삭제)가 발생하면 자동으로 실행되는 처리입니다.', 'データ更新時に自動でログを記録するトリガーを設定しました。'),
  ('デッドロック', 'デッドロック', '교착 상태', 'Deadlock', 'it', '두 개 이상의 처리가 서로 상대방의 자원을 기다리며 무한히 대기하는 상태입니다.', 'デッドロックが発生した場合、片方のトランザクションをロールバックします。'),
  ('排他制御', 'はいたせいぎょ', '배타 제어', 'Exclusive Control', 'it', '여러 사용자가 동시에 같은 데이터를 수정하지 못하도록 잠금을 거는 것입니다.', '排他制御を実装してデータの不整合を防止します。'),
  ('リレーショナルデータベース', 'リレーショナルデータベース', '관계형 데이터베이스', 'Relational Database', 'it', '데이터를 행과 열로 구성된 테이블 형태로 저장하고, 테이블 간의 관계를 정의하여 관리하는 데이터베이스입니다.', 'リレーショナルデータベースでテーブル間の関係を定義しています。'),
  ('NoSQL', 'ノーエスキューエル', 'NoSQL', 'NoSQL', 'it', '관계형 데이터베이스가 아닌 형태의 데이터베이스 총칭입니다. 대량의 비정형 데이터 처리에 적합합니다.', 'NoSQLデータベースを使って柔軟なデータ構造に対応しています。'),
  ('スキーマ', 'スキーマ', '스키마', 'Schema', 'it', '데이터베이스의 구조를 정의한 설계도입니다. 테이블, 컬럼, 관계 등이 포함됩니다.', 'データベースのスキーマを確認してからマイグレーションを実行します。'),
  ('テーブル', 'テーブル', '테이블', 'Table', 'it', '데이터베이스에서 데이터를 행과 열로 정리하여 저장하는 기본 단위입니다.', '新しいテーブルを作成してユーザー情報を管理します。'),
  ('レコード', 'レコード', '레코드', 'Record', 'it', '데이터베이스 테이블에서 한 행에 해당하는 데이터 단위입니다.', 'レコードを追加してデータベースにユーザーを登録します。'),
  ('フィールド', 'フィールド', '필드', 'Field', 'it', '데이터베이스 테이블에서 한 열(컬럼)에 해당하는 항목입니다.', '必須フィールドにNULLが入らないよう制約を設定してください。'),
  ('NULL', 'ヌル', 'NULL', 'NULL', 'it', '데이터베이스에서 값이 없음, 미정, 알 수 없음을 나타내는 특수한 상태입니다.', 'NULLチェックを行ってエラーを防止してください。'),
  ('JOIN', 'ジョイン', 'JOIN', 'JOIN', 'it', '두 개 이상의 테이블을 공통 열을 기준으로 결합하여 데이터를 조회하는 SQL 연산입니다.', 'JOINを使って複数のテーブルからデータを結合して取得します。'),
  ('GROUP BY', 'グループバイ', 'GROUP BY', 'GROUP BY', 'it', 'SQL에서 특정 열의 값이 같은 행끼리 그룹으로 묶어 집계하는 구문입니다.', 'GROUP BY句を使って部署ごとの売上を集計します。'),
  ('ORDER BY', 'オーダーバイ', 'ORDER BY', 'ORDER BY', 'it', 'SQL에서 조회 결과를 특정 열의 값 기준으로 오름차순 또는 내림차순으로 정렬하는 구문입니다.', 'ORDER BY句で日付の新しい順にデータを並び替えます。'),
  ('WHERE句', 'ウェアく', 'WHERE절', 'WHERE Clause', 'it', 'SQL에서 조건을 지정하여 필요한 데이터만 필터링하는 구문입니다.', 'WHERE句で条件を指定して必要なデータだけを取得します。'),
  ('サブクエリ', 'サブクエリ', '서브쿼리', 'Subquery', 'it', 'SQL 문 안에 포함된 또 다른 SQL 문입니다. 중첩 질의라고도 합니다.', 'サブクエリを使って複雑な条件でデータを抽出します。'),
  ('バックアップと復元', 'バックアップとふくげん', '백업과 복원', 'Backup and Restore', 'it', '데이터 손실에 대비하여 데이터를 복사(백업)하고, 필요할 때 원래 상태로 되돌리는(복원) 작업입니다.', 'データベースのバックアップと復元の手順を確認しておいてください。'),
  ('レプリケーション', 'レプリケーション', '복제', 'Replication', 'it', '데이터베이스의 내용을 다른 서버에 실시간으로 복제하여 동기화하는 기술입니다.', 'レプリケーションを構成して読み取り負荷を分散させています。'),
  ('シャーディング', 'シャーディング', '샤딩', 'Sharding', 'it', '대량의 데이터를 여러 데이터베이스 서버에 분산하여 저장하는 기술입니다.', 'シャーディングを導入して大量データの処理性能を向上させました。'),
  ('データウェアハウス', 'データウェアハウス', '데이터 웨어하우스', 'Data Warehouse', 'it', '다양한 시스템의 데이터를 통합하여 분석용으로 저장하는 대규모 데이터 저장소입니다.', 'データウェアハウスに蓄積されたデータを分析してレポートを作成します。'),
  ('ビッグデータ', 'ビッグデータ', '빅데이터', 'Big Data', 'it', '기존 도구로는 처리하기 어려울 정도로 방대한 양의 데이터입니다. 이를 분석하여 새로운 가치를 창출합니다.', 'ビッグデータを活用して顧客の行動パターンを分析しています。')
INSERT INTO it_glossary (term_ja, reading, term_ko, term_en, category, description, example_sentence) VALUES
  ('TCP/IP', 'ティーシーピーアイピー', 'TCP/IP', 'TCP/IP', 'it', '인터넷에서 데이터를 주고받기 위한 기본 통신 규약(프로토콜)의 집합입니다.', 'TCP/IPの基礎知識はネットワークエンジニアにとって必須です。'),
  ('LAN', 'ラン', 'LAN', 'Local Area Network', 'it', '같은 건물이나 사무실 등 좁은 범위에서 컴퓨터를 연결하는 네트워크입니다.', '社内LANに接続してファイルサーバーにアクセスしてください。'),
  ('WAN', 'ワン', 'WAN', 'Wide Area Network', 'it', '본사와 지사 등 멀리 떨어진 장소를 연결하는 넓은 범위의 네트워크입니다.', 'WANを利用して本社と支社のネットワークを接続しています。'),
  ('ルーター', 'ルーター', '라우터', 'Router', 'it', '네트워크 간에 데이터를 최적의 경로로 전달하는 장치입니다.', 'ルーターの設定を変更してネットワークのセグメントを分割します。'),
  ('スイッチ', 'スイッチ', '스위치', 'Switch', 'it', '같은 네트워크 내에서 데이터를 목적지 장치로 정확히 전달하는 장치입니다.', 'スイッチのポートにケーブルを接続してネットワークを構成します。'),
  ('ハブ', 'ハブ', '허브', 'Hub', 'it', '여러 대의 컴퓨터를 연결하여 네트워크를 구성하는 단순한 집선 장치입니다.', 'ハブを使って複数のPCをネットワークに接続しました。'),
  ('プロトコル', 'プロトコル', '프로토콜', 'Protocol', 'it', '컴퓨터 간에 데이터를 주고받기 위해 정해진 통신 규약입니다.', '通信プロトコルを確認してからシステム連携を設計してください。'),
  ('HTTP/HTTPS', 'エイチティーティーピーエイチティーティーピーエス', 'HTTP/HTTPS', 'HTTP/HTTPS', 'it', '웹 브라우저와 웹 서버 사이에서 데이터를 주고받는 프로토콜입니다. HTTPS는 암호화가 추가된 버전입니다.', 'セキュリティのためHTTPSでの通信を必須にしています。'),
  ('FTP', 'エフティーピー', 'FTP', 'File Transfer Protocol', 'it', '네트워크를 통해 파일을 전송하기 위한 프로토콜입니다.', 'FTPサーバーにファイルをアップロードしてください。'),
  ('SMTP', 'エスエムティーピー', 'SMTP', 'Simple Mail Transfer Protocol', 'it', '이메일을 보내기 위해 사용하는 통신 프로토콜입니다.', 'SMTPサーバーの設定を確認してメール送信のテストを行います。'),
  ('POP3', 'ポップスリー', 'POP3', 'Post Office Protocol 3', 'it', '메일 서버에서 이메일을 수신하여 로컬에 다운로드하는 프로토콜입니다.', 'POP3でメールを受信する設定にしています。'),
  ('IMAP', 'アイマップ', 'IMAP', 'Internet Message Access Protocol', 'it', '메일 서버에 이메일을 보관한 채 열람하는 프로토콜입니다. 여러 기기에서 동기화가 가능합니다.', 'IMAPを使えば複数のデバイスでメールを同期できます。'),
  ('DHCP', 'ディーエイチシーピー', 'DHCP', 'Dynamic Host Configuration Protocol', 'it', '네트워크에 접속하는 장치에 자동으로 IP 주소를 할당하는 프로토콜입니다.', 'DHCPサーバーが自動的にIPアドレスを割り当てています。'),
  ('サブネットマスク', 'サブネットマスク', '서브넷 마스크', 'Subnet Mask', 'it', 'IP 주소에서 네트워크 부분과 호스트 부분을 구분하기 위한 값입니다.', 'サブネットマスクを255.255.255.0に設定してください。'),
  ('MACアドレス', 'マックアドレス', 'MAC 주소', 'MAC Address', 'it', '네트워크 장치에 부여된 고유한 물리적 주소입니다. 세계에서 유일한 값을 가집니다.', '機器のMACアドレスを確認してアクセス制御リストに追加してください。'),
  ('ゲートウェイ', 'ゲートウェイ', '게이트웨이', 'Gateway', 'it', '서로 다른 네트워크를 연결하는 출입구 역할을 하는 장치입니다.', 'デフォルトゲートウェイの設定を確認してください。'),
  ('NAT', 'ナット', 'NAT', 'Network Address Translation', 'it', '사설 IP 주소와 공인 IP 주소를 상호 변환하는 기술입니다. 사내 네트워크에서 인터넷 접속에 사용됩니다.', 'NATを使ってプライベートIPアドレスをグローバルIPに変換しています。'),
  ('帯域幅', 'たいいきはば', '대역폭', 'Bandwidth', 'it', '네트워크를 통해 일정 시간 동안 전송할 수 있는 데이터의 최대 양입니다.', '帯域幅が不足しているため、動画配信が遅延しています。'),
  ('パケット', 'パケット', '패킷', 'Packet', 'it', '네트워크에서 데이터를 전송할 때 작은 단위로 분할한 데이터 묶음입니다.', 'パケットの損失率を確認してネットワーク品質を評価します。'),
  ('ドメイン名', 'ドメインめい', '도메인명', 'Domain Name', 'it', '숫자로 된 IP 주소를 사람이 이해하기 쉬운 이름으로 표현한 것입니다. 예: example.com', '新しいドメイン名を取得してWebサイトを公開します。'),
  ('URL', 'ユーアールエル', 'URL', 'Uniform Resource Locator', 'it', '인터넷에서 특정 자원(웹페이지 등)의 위치를 나타내는 주소입니다.', 'APIのURLを確認してからリクエストを送信してください。'),
  ('Wi-Fi', 'ワイファイ', 'Wi-Fi', 'Wi-Fi', 'it', '무선으로 인터넷에 접속할 수 있게 하는 기술입니다.', '会議室のWi-Fiに接続してオンラインミーティングに参加してください。'),
  ('Bluetooth', 'ブルートゥース', '블루투스', 'Bluetooth', 'it', '짧은 거리에서 기기 간에 데이터를 무선으로 주고받는 통신 기술입니다.', 'Bluetoothでキーボードとマウスをパソコンに接続しています。'),
  ('IoT', 'アイオーティー', 'IoT', 'Internet of Things', 'it', '가전제품, 센서 등 다양한 사물이 인터넷에 연결되어 데이터를 주고받는 개념입니다.', 'IoTデバイスのセキュリティ対策が重要な課題になっています。'),
  ('クラウドコンピューティング', 'クラウドコンピューティング', '클라우드 컴퓨팅', 'Cloud Computing', 'it', '인터넷을 통해 서버, 스토리지, 소프트웨어 등의 IT 자원을 필요한 만큼 이용하는 방식입니다.', 'クラウドコンピューティングを活用してインフラコストを削減しました。'),
  ('仮想化', 'かそうか', '가상화', 'Virtualization', 'it', '하나의 물리적 장비 위에 여러 개의 가상 환경을 만드는 기술입니다.', '仮想化技術を使ってサーバーの利用効率を向上させています。'),
  ('VoIP', 'ブイオーアイピー', 'VoIP', 'Voice over IP', 'it', '인터넷을 이용하여 음성 통화를 하는 기술입니다. IP 전화라고도 합니다.', 'VoIPを導入して通話コストを大幅に削減しました。'),
  ('トポロジー', 'トポロジー', '토폴로지', 'Topology', 'it', '네트워크의 물리적 또는 논리적 연결 형태를 나타내는 구조입니다.', 'ネットワークトポロジーを確認してから障害箇所を特定します。'),
  ('QoS', 'キューオーエス', 'QoS', 'Quality of Service', 'it', '네트워크에서 특정 통신에 대해 우선순위를 부여하여 품질을 보장하는 기술입니다.', 'QoSを設定して音声通話の優先度を上げました。'),
  ('5G', 'ファイブジー', '5G', '5G', 'it', '제5세대 이동 통신 시스템으로, 초고속, 초저지연, 대량 접속이 특징입니다.', '5G通信によりリアルタイムの遠隔操作が可能になりました。')
INSERT INTO it_glossary (term_ja, reading, term_ko, term_en, category, description, example_sentence) VALUES
  ('暗号化', 'あんごうか', '암호화', 'Encryption', 'it', '데이터를 제3자가 읽을 수 없도록 특정 규칙에 따라 변환하는 기술입니다. 개인정보나 기밀 데이터를 보호하기 위해 사용됩니다.', '個人情報を送信する際は必ず暗号化を行ってください。'),
  ('復号', 'ふくごう', '복호화', 'Decryption', 'it', '암호화된 데이터를 원래의 읽을 수 있는 형태로 되돌리는 과정입니다.', '受信したデータを復号してから内容を確認します。'),
  ('マルウェア', 'マルウェア', '멀웨어', 'Malware', 'it', '컴퓨터에 피해를 주기 위해 만들어진 악성 소프트웨어의 총칭입니다. 바이러스, 웜, 트로이목마 등이 포함됩니다.', 'マルウェア対策ソフトを最新の状態に保ってください。'),
  ('ランサムウェア', 'ランサムウェア', '랜섬웨어', 'Ransomware', 'it', '컴퓨터의 파일을 암호화하여 사용할 수 없게 만든 뒤 돈을 요구하는 악성 프로그램입니다.', 'ランサムウェアの被害を防ぐため、定期的にバックアップを取ってください。'),
  ('フィッシング', 'フィッシング', '피싱', 'Phishing', 'it', '신뢰할 수 있는 기관을 사칭하여 개인정보를 빼내는 사기 수법입니다. 주로 이메일이나 가짜 웹사이트를 이용합니다.', 'フィッシングメールに注意して、不審なリンクをクリックしないでください。'),
  ('二要素認証', 'にようそにんしょう', '이중 인증', 'Two-Factor Authentication', 'it', '비밀번호 외에 한 가지 추가 인증 수단을 사용하여 보안을 강화하는 방법입니다.', '社内システムには二要素認証を設定してください。'),
  ('多要素認証', 'たようそにんしょう', '다중 인증', 'Multi-Factor Authentication', 'it', '두 가지 이상의 서로 다른 인증 수단을 조합하여 본인 확인을 하는 보안 방식입니다.', 'セキュリティ強化のため多要素認証を導入しました。'),
  ('不正アクセス', 'ふせいあくせす', '불법 접근', 'Unauthorized Access', 'it', '허가 없이 타인의 컴퓨터나 시스템에 침입하는 행위입니다. 법률로 금지되어 있습니다.', '不正アクセスを検知した場合は直ちに報告してください。'),
  ('脆弱性', 'ぜいじゃくせい', '취약점', 'Vulnerability', 'it', '소프트웨어나 시스템의 보안상 약점으로, 공격자에게 악용될 수 있는 결함입니다.', '脆弱性診断を実施してセキュリティリスクを洗い出します。'),
  ('セキュリティポリシー', 'セキュリティポリシー', '보안 정책', 'Security Policy', 'it', '조직의 정보 보안에 관한 기본 방침과 규칙을 정리한 문서입니다.', 'セキュリティポリシーに従ってパスワードを管理してください。'),
  ('情報セキュリティ', 'じょうほうせきゅりてぃ', '정보 보안', 'Information Security', 'it', '정보의 기밀성, 완전성, 가용성을 보호하기 위한 활동과 기술의 총칭입니다.', '情報セキュリティ研修を全社員に実施しています。'),
  ('機密性', 'きみつせい', '기밀성', 'Confidentiality', 'it', '허가된 사람만 정보에 접근할 수 있도록 보호하는 성질입니다. 정보 보안의 3요소 중 하나입니다.', '機密性を確保するためにアクセス権限を適切に設定してください。'),
  ('完全性', 'かんぜんせい', '무결성', 'Integrity', 'it', '정보가 허가 없이 변경되거나 파괴되지 않도록 보호하는 성질입니다. 정보 보안의 3요소 중 하나입니다.', 'データの完全性を保つためにチェックサムを使用しています。'),
  ('リスクアセスメント', 'リスクアセスメント', '리스크 평가', 'Risk Assessment', 'it', '잠재적인 위험을 식별하고 그 영향과 발생 가능성을 평가하는 과정입니다.', 'リスクアセスメントを行い、優先的に対応すべき脅威を特定しました。'),
  ('バイオメトリクス認証', 'バイオメトリクスにんしょう', '생체 인증', 'Biometric Authentication', 'it', '지문, 얼굴, 홍채 등 신체 특징을 이용하여 본인을 확인하는 인증 방식입니다.', 'オフィスの入退室にバイオメトリクス認証を導入しました。'),
  ('デジタル署名', 'デジタルしょめい', '디지털 서명', 'Digital Signature', 'it', '전자 문서의 작성자와 내용이 변경되지 않았음을 증명하는 전자적 서명입니다.', 'デジタル署名を付与して文書の真正性を保証します。'),
  ('公開鍵暗号', 'こうかいかぎあんごう', '공개키 암호', 'Public Key Cryptography', 'it', '암호화와 복호화에 서로 다른 키(공개키와 비밀키)를 사용하는 암호 방식입니다.', '公開鍵暗号を使ってセキュアな通信を実現しています。'),
  ('共通鍵暗号', 'きょうつうかぎあんごう', '공통키 암호', 'Symmetric Key Cryptography', 'it', '암호화와 복호화에 동일한 키를 사용하는 암호 방식입니다. 처리 속도가 빠른 것이 장점입니다.', '共通鍵暗号はデータの暗号化速度が速いため、大量データの処理に適しています。'),
  ('WAF', 'ワフ', 'WAF', 'Web Application Firewall', 'it', '웹 애플리케이션에 대한 공격을 탐지하고 차단하는 전문 방화벽입니다.', 'WAFを導入してWebアプリケーションへの攻撃を防御しています。'),
  ('IDS', 'アイディーエス', 'IDS', 'Intrusion Detection System', 'it', '네트워크나 시스템에 대한 불법 침입을 탐지하는 시스템입니다.', 'IDSが不審な通信パターンを検知しました。'),
  ('IPS', 'アイピーエス', 'IPS', 'Intrusion Prevention System', 'it', '불법 침입을 탐지할 뿐만 아니라 자동으로 차단까지 수행하는 시스템입니다.', 'IPSを導入して不正アクセスをリアルタイムで遮断しています。'),
  ('ペネトレーションテスト', 'ペネトレーションテスト', '모의 침투 테스트', 'Penetration Test', 'it', '실제 해커의 공격을 모방하여 시스템의 보안 취약점을 찾아내는 테스트입니다.', 'リリース前にペネトレーションテストを実施してセキュリティを確認します。'),
  ('SQLインジェクション', 'エスキューエルインジェクション', 'SQL 인젝션', 'SQL Injection', 'it', '웹 애플리케이션의 입력란에 악의적인 SQL 코드를 삽입하여 데이터베이스를 조작하는 공격입니다.', 'SQLインジェクション対策としてプリペアドステートメントを使用してください。'),
  ('クロスサイトスクリプティング', 'クロスサイトスクリプティング', '크로스 사이트 스크립팅', 'Cross-Site Scripting', 'it', '웹사이트에 악성 스크립트를 삽입하여 사용자의 정보를 탈취하는 공격 기법입니다.', 'クロスサイトスクリプティングを防ぐために入力値のサニタイズを行ってください。'),
  ('DDoS攻撃', 'ディードスこうげき', 'DDoS 공격', 'DDoS Attack', 'it', '다수의 컴퓨터에서 동시에 대량의 요청을 보내 서버를 마비시키는 공격입니다.', 'DDoS攻撃に備えてCDNとWAFの対策を強化しました。'),
  ('ゼロデイ攻撃', 'ゼロデイこうげき', '제로데이 공격', 'Zero-Day Attack', 'it', '소프트웨어의 보안 취약점이 발견된 후 수정 패치가 나오기 전에 그 취약점을 악용하는 공격입니다.', 'ゼロデイ攻撃のリスクを最小限にするためソフトウェアを常に最新に保ちましょう。'),
  ('パスワードポリシー', 'パスワードポリシー', '비밀번호 정책', 'Password Policy', 'it', '비밀번호의 길이, 복잡도, 변경 주기 등에 관한 규칙입니다.', 'パスワードポリシーに従い、8文字以上の英数字記号を含むパスワードを設定してください。'),
  ('アクセス制御', 'アクセスせいぎょ', '접근 제어', 'Access Control', 'it', '시스템이나 데이터에 대한 접근 권한을 관리하고 통제하는 것입니다.', 'アクセス制御を適切に設定して、必要な権限のみ付与してください。'),
  ('情報漏洩', 'じょうほうろうえい', '정보 유출', 'Information Leakage', 'it', '기밀 정보나 개인정보가 외부에 유출되는 사고입니다. 기업에 큰 피해를 줄 수 있습니다.', '情報漏洩を防ぐため、USBメモリの使用を制限しています。'),
  ('監査ログ', 'かんさろぐ', '감사 로그', 'Audit Log', 'it', '시스템에서 누가 언제 어떤 작업을 했는지 기록한 로그입니다. 보안 사고 조사에 필수적입니다.', '監査ログを定期的に確認して不審な操作がないか監視しています。'),
  ('インシデント対応', 'インシデントたいおう', '인시던트 대응', 'Incident Response', 'it', '보안 사고가 발생했을 때 피해를 최소화하기 위해 신속하게 대처하는 절차입니다.', 'インシデント対応マニュアルに従って迅速に対処してください。'),
  ('BCP', 'ビーシーピー', 'BCP', 'Business Continuity Plan', 'it', '재해나 사고 발생 시에도 사업을 지속하기 위한 계획입니다.', 'BCPを策定して、災害時の業務継続体制を整備しました。'),
  ('ディザスタリカバリ', 'ディザスタリカバリ', '재해 복구', 'Disaster Recovery', 'it', '재해로 인한 시스템 장애 시 정상 상태로 복구하기 위한 계획과 절차입니다.', 'ディザスタリカバリの訓練を年に一度実施しています。')
INSERT INTO it_glossary (term_ja, reading, term_ko, term_en, category, description, example_sentence) VALUES
  ('SWOT分析', 'スウォットぶんせき', 'SWOT 분석', 'SWOT Analysis', 'business', '강점(Strength), 약점(Weakness), 기회(Opportunity), 위협(Threat)을 분석하여 경영 전략을 세우는 기법입니다.', 'SWOT分析を行って新規事業の方向性を検討しましょう。'),
  ('ROI', 'アールオーアイ', 'ROI', 'Return on Investment', 'business', '투자한 비용에 대해 얼마나 이익을 얻었는지를 나타내는 지표입니다.', 'システム導入のROIを算出して投資判断の材料にします。'),
  ('SaaS', 'サース', 'SaaS', 'Software as a Service', 'business', '인터넷을 통해 소프트웨어를 서비스로 제공하는 형태입니다. 설치 없이 바로 사용할 수 있습니다.', 'SaaS型のサービスを導入して初期コストを抑えました。'),
  ('PaaS', 'パース', 'PaaS', 'Platform as a Service', 'business', '애플리케이션 개발에 필요한 플랫폼(실행 환경, DB 등)을 인터넷을 통해 제공하는 서비스입니다.', 'PaaSを利用してアプリケーションの開発環境を構築しました。'),
  ('IaaS', 'イアース', 'IaaS', 'Infrastructure as a Service', 'business', '서버, 스토리지, 네트워크 등 IT 인프라를 인터넷을 통해 제공하는 서비스입니다.', 'IaaSを活用してサーバーインフラを柔軟に構築しています。'),
  ('知的財産権', 'ちてきざいさんけん', '지적 재산권', 'Intellectual Property Rights', 'business', '발명, 저작물, 상표 등 인간의 지적 창작물에 대한 법적 권리의 총칭입니다.', '知的財産権を適切に管理してビジネスの競争力を守りましょう。'),
  ('コンプライアンス', 'コンプライアンス', '컴플라이언스', 'Compliance', 'business', '법령이나 사회 규범을 준수하는 것입니다. 기업 경영에서 매우 중요한 개념입니다.', 'コンプライアンス研修を全社員に実施しています。'),
  ('個人情報保護法', 'こじんじょうほうほごほう', '개인정보보호법', 'Personal Information Protection Act', 'business', '개인정보의 취급에 관한 규칙을 정한 법률입니다. 사업자가 지켜야 할 의무를 규정합니다.', '個人情報保護法に基づいてデータの取り扱いルールを定めています。'),
  ('損益分岐点', 'そんえきぶんきてん', '손익분기점', 'Break-Even Point', 'business', '매출과 비용이 같아져 이익도 손실도 없는 지점입니다. 이 이상 팔면 이익이 발생합니다.', '損益分岐点を計算してプロジェクトの採算性を評価します。'),
  ('RFP', 'アールエフピー', 'RFP', 'Request for Proposal', 'business', '시스템 도입 시 발주자가 공급자에게 제안을 요청하는 문서입니다.', 'RFPを作成してベンダーに提案を依頼しました。'),
  ('NDA', 'エヌディーエー', 'NDA', 'Non-Disclosure Agreement', 'business', '비밀정보를 외부에 공개하지 않기로 약속하는 비밀유지 계약서입니다.', 'プロジェクト開始前にNDAを締結してください。'),
  ('著作権', 'ちょさくけん', '저작권', 'Copyright', 'business', '문학, 음악, 소프트웨어 등 창작물에 대해 창작자가 갖는 법적 권리입니다.', '他社のソースコードには著作権があるため無断使用はできません。'),
  ('特許権', 'とっきょけん', '특허권', 'Patent Right', 'business', '새로운 발명에 대해 일정 기간 독점적으로 사용할 수 있는 권리입니다.', '新しいアルゴリズムについて特許権を取得しました。'),
  ('商標権', 'しょうひょうけん', '상표권', 'Trademark Right', 'business', '상품이나 서비스의 이름, 로고 등을 독점적으로 사용할 수 있는 권리입니다.', '自社ブランドの商標権を登録して保護しています。'),
  ('CSR', 'シーエスアール', 'CSR', 'Corporate Social Responsibility', 'business', '기업이 사회적 책임을 다하기 위해 수행하는 활동입니다. 환경 보호, 사회 공헌 등이 포함됩니다.', 'CSR活動として地域のIT教育支援を行っています。'),
  ('ESG', 'イーエスジー', 'ESG', 'Environmental Social Governance', 'business', '환경(E), 사회(S), 지배구조(G)를 고려한 기업 경영 방식입니다. 투자 판단의 기준이 됩니다.', 'ESG経営を推進して持続可能な成長を目指しています。'),
  ('DX', 'ディーエックス', 'DX', 'Digital Transformation', 'business', '디지털 기술을 활용하여 기업의 업무 방식이나 비즈니스 모델을 근본적으로 변혁하는 것입니다.', 'DXを推進して業務プロセスのデジタル化を進めています。'),
  ('AI', 'エーアイ', 'AI', 'Artificial Intelligence', 'business', '인간의 지능적인 행동을 컴퓨터로 구현하는 기술입니다. 학습, 판단, 예측 등이 가능합니다.', 'AIを活用して業務の自動化と効率化を図っています。'),
  ('BI', 'ビーアイ', 'BI', 'Business Intelligence', 'business', '축적된 데이터를 분석하여 경영 의사결정에 활용하는 도구와 방법론입니다.', 'BIツールを使って売上データを可視化して分析しています。'),
  ('ERP', 'イーアールピー', 'ERP', 'Enterprise Resource Planning', 'business', '기업의 경영 자원(인사, 회계, 생산 등)을 통합적으로 관리하는 시스템입니다.', 'ERPを導入して社内の業務プロセスを統合管理しています。'),
  ('CRM', 'シーアールエム', 'CRM', 'Customer Relationship Management', 'business', '고객과의 관계를 체계적으로 관리하여 고객 만족도와 매출을 높이는 경영 기법입니다.', 'CRMシステムで顧客情報を一元管理しています。'),
  ('SCM', 'エスシーエム', 'SCM', 'Supply Chain Management', 'business', '원재료 조달부터 생산, 유통, 판매까지의 공급 과정을 전체적으로 관리하는 경영 기법입니다.', 'SCMを最適化してコスト削減とリードタイム短縮を実現しました。'),
  ('FinTech', 'フィンテック', '핀테크', 'FinTech', 'business', '금융(Finance)과 기술(Technology)을 결합한 새로운 금융 서비스입니다.', 'FinTech企業との連携で新しい決済サービスを開発しています。'),
  ('RPA', 'アールピーエー', 'RPA', 'Robotic Process Automation', 'business', '사무 작업을 소프트웨어 로봇이 자동으로 수행하도록 하는 기술입니다.', 'RPAを導入して定型業務を自動化し、業務効率を向上させました。'),
  ('アウトソーシング', 'アウトソーシング', '아웃소싱', 'Outsourcing', 'business', '자사의 업무 일부를 외부 전문 업체에 위탁하는 경영 방식입니다.', 'IT運用をアウトソーシングしてコア業務に集中しています。'),
  ('BPO', 'ビーピーオー', 'BPO', 'Business Process Outsourcing', 'business', '기업의 업무 프로세스 전체를 외부에 위탁하는 것입니다. 단순 위탁보다 범위가 넓습니다.', '経理業務をBPOに委託して社内リソースを最適化しました。'),
  ('M&A', 'エムアンドエー', 'M&A', 'Mergers and Acquisitions', 'business', '기업의 합병(Merger)과 인수(Acquisition)를 통한 경영 전략입니다.', 'M&Aによって新たな技術力と顧客基盤を獲得しました。'),
  ('IR', 'アイアール', 'IR', 'Investor Relations', 'business', '기업이 투자자에게 경영 상황이나 재무 정보를 제공하는 활동입니다.', 'IR資料を作成して投資家向けに四半期決算を報告します。'),
  ('内部統制', 'ないぶとうせい', '내부 통제', 'Internal Control', 'business', '기업 내부에서 업무가 적절하게 수행되도록 관리하는 체계입니다. 부정 방지와 업무 효율화를 목적으로 합니다.', '内部統制を強化して不正リスクを低減させます。'),
  ('コーポレートガバナンス', 'コーポレートガバナンス', '기업 지배구조', 'Corporate Governance', 'business', '기업 경영을 감시하고 통제하는 체계입니다. 경영의 투명성과 건전성을 확보합니다.', 'コーポレートガバナンスを強化して経営の透明性を向上させています。'),
  ('リスクマネジメント', 'リスクマネジメント', '리스크 관리', 'Risk Management', 'business', '잠재적인 위험을 사전에 파악하고, 대응 방안을 수립하여 손실을 최소화하는 활동입니다.', 'リスクマネジメントを徹底してプロジェクトの成功確率を高めましょう。'),
  ('PDCAサイクル', 'ピーディーシーエーサイクル', 'PDCA 사이클', 'PDCA Cycle', 'business', '계획(Plan), 실행(Do), 확인(Check), 개선(Act)을 반복하여 업무를 지속적으로 개선하는 방법입니다.', 'PDCAサイクルを回して業務品質を継続的に改善しています。'),
  ('KGI', 'ケージーアイ', 'KGI', 'Key Goal Indicator', 'business', '최종 목표의 달성 여부를 판단하기 위한 핵심 지표입니다. KPI와 함께 사용됩니다.', 'KGIとして年間売上目標を設定しました。'),
  ('OKR', 'オーケーアール', 'OKR', 'Objectives and Key Results', 'business', '조직의 목표(Objective)와 그것을 측정하는 핵심 결과(Key Result)를 설정하는 목표 관리 기법입니다.', 'OKRを導入してチームの目標を明確にしました。'),
  ('バリューチェーン', 'バリューチェーン', '가치 사슬', 'Value Chain', 'business', '기업의 활동을 원재료 조달부터 판매까지 단계별로 나누어 각 단계에서 창출되는 가치를 분석하는 기법입니다.', 'バリューチェーン分析を行って競争優位を明確にしましょう。'),
  ('マーケティングミックス', 'マーケティングミックス', '마케팅 믹스', 'Marketing Mix', 'business', '제품(Product), 가격(Price), 유통(Place), 판촉(Promotion)의 4가지 요소를 조합하여 마케팅 전략을 수립하는 것입니다.', 'マーケティングミックスの4Pを分析して戦略を立案します。'),
  ('ブルーオーシャン戦略', 'ブルーオーシャンせんりゃく', '블루오션 전략', 'Blue Ocean Strategy', 'business', '경쟁이 없는 새로운 시장을 개척하여 높은 수익을 창출하는 경영 전략입니다.', 'ブルーオーシャン戦略で未開拓の市場を狙います。'),
  ('競争優位', 'きょうそうゆうい', '경쟁 우위', 'Competitive Advantage', 'business', '경쟁 기업보다 우월한 위치를 차지하여 더 높은 수익을 올릴 수 있는 상태입니다.', '独自の技術力を活かして競争優位を確立しています。'),
  ('イノベーション', 'イノベーション', '혁신', 'Innovation', 'business', '기존과는 다른 새로운 기술이나 아이디어를 도입하여 큰 변화를 일으키는 것입니다.', 'イノベーションを推進して新しいビジネスモデルを構築します。'),
  ('ベンチマーキング', 'ベンチマーキング', '벤치마킹', 'Benchmarking', 'business', '우수한 기업의 사례를 분석하고 자사에 적용하여 경쟁력을 높이는 경영 기법입니다.', '業界トップ企業をベンチマーキングして改善点を洗い出しました。'),
  ('フィージビリティスタディ', 'フィージビリティスタディ', '타당성 조사', 'Feasibility Study', 'business', '프로젝트나 사업의 실현 가능성을 사전에 조사하고 평가하는 활동입니다.', 'フィージビリティスタディを行って事業化の可否を判断します。'),
  ('標準化', 'ひょうじゅんか', '표준화', 'Standardization', 'business', '제품이나 프로세스의 규격을 통일하여 효율성과 호환성을 높이는 활동입니다.', '業務プロセスの標準化を進めて効率を向上させましょう。'),
  ('ISO', 'アイエスオー', 'ISO', 'International Organization for Standardization', 'business', '국제 표준화 기구로, 다양한 분야의 국제 규격을 제정합니다.', 'ISO認証を取得して品質管理体制を証明しています。'),
  ('ISMS', 'アイエスエムエス', 'ISMS', 'Information Security Management System', 'business', '조직의 정보 보안을 체계적으로 관리하기 위한 프레임워크입니다. ISO 27001이 대표적 기준입니다.', 'ISMSの認証を取得してセキュリティ管理体制を強化しました。'),
  ('プライバシーマーク', 'プライバシーマーク', '프라이버시 마크', 'Privacy Mark', 'business', '개인정보를 적절히 관리하고 있음을 인증하는 일본의 제도입니다.', 'プライバシーマークを取得してお客様の信頼を得ています。'),
  ('不正競争防止法', 'ふせいきょうそうぼうしほう', '부정경쟁방지법', 'Unfair Competition Prevention Act', 'business', '영업 비밀 침해, 모방품 판매 등 부정한 경쟁 행위를 금지하는 법률입니다.', '不正競争防止法に基づいて営業秘密の管理を徹底しています。'),
  ('労働基準法', 'ろうどうきじゅんほう', '노동기준법', 'Labor Standards Act', 'business', '근로자의 근로 조건에 관한 최저 기준을 정한 법률입니다. 근무 시간, 휴일, 급여 등을 규정합니다.', '労働基準法に基づいて残業時間を適切に管理してください。'),
  ('下請法', 'したうけほう', '하도급법', 'Subcontract Act', 'business', '발주 기업이 하도급 업체에 대해 부당한 행위를 하지 못하도록 규제하는 법률입니다.', '下請法を遵守して外注先との適正な取引を行います。'),
  ('電子契約', 'でんしけいやく', '전자 계약', 'Electronic Contract', 'business', '종이 대신 전자적 방식으로 계약을 체결하는 것입니다. 전자 서명을 사용합니다.', '電子契約を導入して契約手続きの効率化とペーパーレス化を実現しました。')
